def search_wikipedia(query, language_code, limit=None, cursor=None, sort=None, status=None, **_extra):
    import json, os, datetime, time, base64, hashlib, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0475000" if __import__("os").path.isdir("./environment_mix/0475000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- auth context (ambient) + rate limit ----
    clients = _load("api_clients.json")
    req_logs = _load("request_logs.json")

    def _pick_client_for_call():
        # No explicit credential parameter in this API, so choose an active client that can serve.
        # If none exist, treat as unauthenticated/anonymous (client_id None) with no explicit rate limit row.
        active = [c for c in clients if isinstance(c, dict) and c.get("status") == "active"]
        if not active:
            return None
        # Choose the one with highest limit to reduce false RATE_LIMIT under shared store usage.
        active.sort(key=lambda r: int(r.get("rate_limit_per_minute") or 0), reverse=True)
        return active[0]

    client = _pick_client_for_call()
    client_id = client.get("id") if client else None

    def _count_last_minute(cid):
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        n = 0
        for r in req_logs:
            if not isinstance(r, dict):
                continue
            if r.get("client_id") != cid:
                continue
            ts = r.get("created_at")
            try:
                if not isinstance(ts, str):
                    continue
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff:
                n += 1
        return n

    def _log(tool_name, input_obj, http_status, cache_hit, matched_article_id=None, error_code=None, latency_ms=0):
        nonlocal req_logs
        # id convention: req_<ulidish>
        rid = "req_" + base64.b32encode(hashlib.sha256((tool_name + now + str(time.time())).encode("utf-8")).digest())[:16].decode("ascii").rstrip("=").lower()
        row = {
            "id": rid,
            "client_id": client_id,
            "tool_name": tool_name,
            "input": input_obj if isinstance(input_obj, dict) else {},
            "matched_article_id": matched_article_id,
            "http_status": int(http_status),
            "cache_hit": bool(cache_hit),
            "latency_ms": int(max(0, min(600000, latency_ms))),
            "error_code": error_code,
            "created_at": now,
            "updated_at": now,
        }
        req_logs.append(row)
        _save("request_logs.json", req_logs)

    # Rate limit enforcement (429) must still log.
    if client and isinstance(client.get("rate_limit_per_minute"), int):
        used = _count_last_minute(client_id)
        if used >= client["rate_limit_per_minute"]:
            latency_ms = int((time.time() - t0) * 1000)
            _log(
                "search_wikipedia",
                {"query": query, "language_code": language_code, "limit": limit, "cursor": cursor, "sort": sort, "status": status},
                429,
                False,
                matched_article_id=None,
                error_code="RATE_LIMITED",
                latency_ms=latency_ms,
            )
            return _err("RATE_LIMIT", "Rate limit exceeded.", http_status=429)

    # ---- validation ----
    if not isinstance(query, str) or not query.strip():
        latency_ms = int((time.time() - t0) * 1000)
        _log("search_wikipedia", {"query": query, "language_code": language_code, "limit": limit, "cursor": cursor, "sort": sort, "status": status}, 400, False, error_code="VALIDATION_ERROR", latency_ms=latency_ms)
        return _err("VALIDATION_ERROR", "query must be a non-empty string.", http_status=400)
    if not isinstance(language_code, str) or not (2 <= len(language_code) <= 12):
        latency_ms = int((time.time() - t0) * 1000)
        _log("search_wikipedia", {"query": query, "language_code": language_code, "limit": limit, "cursor": cursor, "sort": sort, "status": status}, 400, False, error_code="VALIDATION_ERROR", latency_ms=latency_ms)
        return _err("VALIDATION_ERROR", "language_code must be a string of length 2–12.", http_status=400)

    if limit is None:
        limit = 10
    if not isinstance(limit, int) or limit < 1 or limit > 50:
        latency_ms = int((time.time() - t0) * 1000)
        _log("search_wikipedia", {"query": query, "language_code": language_code, "limit": limit, "cursor": cursor, "sort": sort, "status": status}, 400, False, error_code="VALIDATION_ERROR", latency_ms=latency_ms)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 50.", http_status=400)

    if sort is None:
        sort = "relevance"
    if sort not in ("relevance", "popularity"):
        latency_ms = int((time.time() - t0) * 1000)
        _log("search_wikipedia", {"query": query, "language_code": language_code, "limit": limit, "cursor": cursor, "sort": sort, "status": status}, 400, False, error_code="VALIDATION_ERROR", latency_ms=latency_ms)
        return _err("VALIDATION_ERROR", "sort must be one of: relevance, popularity.", http_status=400)

    if status is None:
        status = "active"
    if status not in ("active", "stale", "disabled"):
        latency_ms = int((time.time() - t0) * 1000)
        _log("search_wikipedia", {"query": query, "language_code": language_code, "limit": limit, "cursor": cursor, "sort": sort, "status": status}, 400, False, error_code="VALIDATION_ERROR", latency_ms=latency_ms)
        return _err("VALIDATION_ERROR", "status must be one of: active, stale, disabled.", http_status=400)

    start = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            latency_ms = int((time.time() - t0) * 1000)
            _log("search_wikipedia", {"query": query, "language_code": language_code, "limit": limit, "cursor": cursor, "sort": sort, "status": status}, 400, False, error_code="VALIDATION_ERROR", latency_ms=latency_ms)
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided.", http_status=400)
        # cursor format: base64url({"o": int})
        try:
            pad = "=" * ((4 - (len(cursor) % 4)) % 4)
            payload = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(payload)
            if not isinstance(obj, dict) or not isinstance(obj.get("o"), int) or obj["o"] < 0:
                raise ValueError("bad cursor")
            start = obj["o"]
        except Exception:
            latency_ms = int((time.time() - t0) * 1000)
            _log("search_wikipedia", {"query": query, "language_code": language_code, "limit": limit, "cursor": cursor, "sort": sort, "status": status}, 400, False, error_code="VALIDATION_ERROR", latency_ms=latency_ms)
            return _err("VALIDATION_ERROR", "cursor is malformed.", http_status=400)

    # ---- read + enforce FK integrity and article status requirement ----
    articles = _load("articles.json")
    art_by_id = {a.get("id"): a for a in articles if isinstance(a, dict) and isinstance(a.get("id"), str)}

    index_rows = _load("search_index.json")
    q = query.strip().lower()

    def _score(row):
        title = (row.get("title") or "")
        nt = (row.get("normalized_title") or "")
        kws = row.get("keywords") if isinstance(row.get("keywords"), list) else []
        title_l = title.lower()
        nt_l = nt.lower()
        s = 0.0
        if q == nt_l:
            s += 1000.0
        if title_l.startswith(q) or nt_l.startswith(q):
            s += 200.0
        if q in title_l or q in nt_l:
            s += 50.0
        for kw in kws:
            if not isinstance(kw, str):
                continue
            kl = kw.lower()
            if kl == q:
                s += 150.0
            elif kl.startswith(q):
                s += 40.0
            elif q in kl:
                s += 10.0
        return s

    filtered = []
    for r in index_rows:
        if not isinstance(r, dict):
            continue
        if r.get("language_code") != language_code:
            continue
        if r.get("status") != status:
            continue
        aid = r.get("article_id")
        a = art_by_id.get(aid)
        # enforce FK integrity by excluding broken rows
        if not a:
            continue
        if a.get("status") not in ("active", "redirect"):
            continue
        # query match
        title = (r.get("title") or "")
        nt = (r.get("normalized_title") or "")
        kws = r.get("keywords") if isinstance(r.get("keywords"), list) else []
        hay = " ".join([title, nt] + [k for k in kws if isinstance(k, str)]).lower()
        if q not in hay:
            continue
        rr = dict(r)
        rr["_relevance"] = _score(r)
        filtered.append(rr)

    if sort == "popularity":
        filtered.sort(key=lambda x: (float(x.get("popularity_score") or 0.0), float(x.get("_relevance") or 0.0)), reverse=True)
    else:
        filtered.sort(key=lambda x: (float(x.get("_relevance") or 0.0), float(x.get("popularity_score") or 0.0)), reverse=True)

    total = len(filtered)
    page = filtered[start:start + limit]
    next_cursor = None
    has_more = start + limit < total
    if has_more:
        payload = json.dumps({"o": start + limit}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    # response shaping: include article snapshot info
    results = []
    for r in page:
        a = art_by_id.get(r.get("article_id"))
        results.append({
            "article_id": r.get("article_id"),
            "language_code": r.get("language_code"),
            "title": r.get("title"),
            "wikipedia_url": a.get("wikipedia_url") if isinstance(a, dict) else None,
            "page_id": a.get("page_id") if isinstance(a, dict) else None,
            "popularity_score": r.get("popularity_score"),
        })

    latency_ms = int((time.time() - t0) * 1000)
    _log(
        "search_wikipedia",
        {"query": query, "language_code": language_code, "limit": limit, "cursor": cursor, "sort": sort, "status": status},
        200,
        True,
        matched_article_id=None,
        error_code=None,
        latency_ms=latency_ms,
    )
    return {
        "http_status": 200,
        "results": results,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort": sort,
            "status": status,
            "language_code": language_code,
        },
    }

def get_article(language_code, article_id=None, title=None, page_id=None, format=None, force_refresh=None, **_extra):
    import json, os, datetime, time, base64, hashlib, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0475000" if __import__("os").path.isdir("./environment_mix/0475000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    clients = _load("api_clients.json")
    req_logs = _load("request_logs.json")

    def _pick_client_for_call():
        active = [c for c in clients if isinstance(c, dict) and c.get("status") == "active"]
        if not active:
            return None
        active.sort(key=lambda r: int(r.get("rate_limit_per_minute") or 0), reverse=True)
        return active[0]

    client = _pick_client_for_call()
    client_id = client.get("id") if client else None

    def _count_last_minute(cid):
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        n = 0
        for r in req_logs:
            if not isinstance(r, dict):
                continue
            if r.get("client_id") != cid:
                continue
            ts = r.get("created_at")
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff:
                n += 1
        return n

    def _log(input_obj, http_status, cache_hit, matched_article_id=None, error_code=None, latency_ms=0):
        nonlocal req_logs
        rid = "req_" + base64.b32encode(hashlib.sha256(("get_article" + now + str(time.time())).encode("utf-8")).digest())[:16].decode("ascii").rstrip("=").lower()
        row = {
            "id": rid,
            "client_id": client_id,
            "tool_name": "get_article",
            "input": input_obj if isinstance(input_obj, dict) else {},
            "matched_article_id": matched_article_id,
            "http_status": int(http_status),
            "cache_hit": bool(cache_hit),
            "latency_ms": int(max(0, min(600000, latency_ms))),
            "error_code": error_code,
            "created_at": now,
            "updated_at": now,
        }
        req_logs.append(row)
        _save("request_logs.json", req_logs)

    if client and isinstance(client.get("rate_limit_per_minute"), int):
        if _count_last_minute(client_id) >= client["rate_limit_per_minute"]:
            latency_ms = int((time.time() - t0) * 1000)
            _log({"article_id": article_id, "title": title, "page_id": page_id, "language_code": language_code, "format": format, "force_refresh": force_refresh}, 429, False, None, "RATE_LIMITED", latency_ms)
            return _err("RATE_LIMIT", "Rate limit exceeded.", http_status=429)

    # validation
    if not isinstance(language_code, str) or not (2 <= len(language_code) <= 12):
        latency_ms = int((time.time() - t0) * 1000)
        _log({"article_id": article_id, "title": title, "page_id": page_id, "language_code": language_code, "format": format, "force_refresh": force_refresh}, 400, False, None, "VALIDATION_ERROR", latency_ms)
        return _err("VALIDATION_ERROR", "language_code must be a string of length 2–12.", http_status=400)

    if format is None:
        format = "both"
    if format not in ("html", "text", "both"):
        latency_ms = int((time.time() - t0) * 1000)
        _log({"article_id": article_id, "title": title, "page_id": page_id, "language_code": language_code, "format": format, "force_refresh": force_refresh}, 400, False, None, "VALIDATION_ERROR", latency_ms)
        return _err("VALIDATION_ERROR", "format must be one of: html, text, both.", http_status=400)

    if force_refresh is None:
        force_refresh = False
    if not isinstance(force_refresh, bool):
        latency_ms = int((time.time() - t0) * 1000)
        _log({"article_id": article_id, "title": title, "page_id": page_id, "language_code": language_code, "format": format, "force_refresh": force_refresh}, 400, False, None, "VALIDATION_ERROR", latency_ms)
        return _err("VALIDATION_ERROR", "force_refresh must be a boolean.", http_status=400)

    if article_id is not None:
        if not isinstance(article_id, str) or not re.match(r"^wik_art_[0-9A-HJKMNP-TV-Z]{10,}$", article_id):
            latency_ms = int((time.time() - t0) * 1000)
            _log({"article_id": article_id, "title": title, "page_id": page_id, "language_code": language_code, "format": format, "force_refresh": force_refresh}, 400, False, None, "VALIDATION_ERROR", latency_ms)
            return _err("VALIDATION_ERROR", "article_id does not match expected pattern.", http_status=400)

    if article_id is None:
        # require either title or page_id
        if title is None and page_id is None:
            latency_ms = int((time.time() - t0) * 1000)
            _log({"article_id": article_id, "title": title, "page_id": page_id, "language_code": language_code, "format": format, "force_refresh": force_refresh}, 400, False, None, "VALIDATION_ERROR", latency_ms)
            return _err("VALIDATION_ERROR", "Provide article_id or (title or page_id) with language_code.", http_status=400)
        if title is not None and (not isinstance(title, str) or not title.strip()):
            latency_ms = int((time.time() - t0) * 1000)
            _log({"article_id": article_id, "title": title, "page_id": page_id, "language_code": language_code, "format": format, "force_refresh": force_refresh}, 400, False, None, "VALIDATION_ERROR", latency_ms)
            return _err("VALIDATION_ERROR", "title must be a non-empty string.", http_status=400)
        if page_id is not None and (not isinstance(page_id, int) or page_id <= 0):
            latency_ms = int((time.time() - t0) * 1000)
            _log({"article_id": article_id, "title": title, "page_id": page_id, "language_code": language_code, "format": format, "force_refresh": force_refresh}, 400, False, None, "VALIDATION_ERROR", latency_ms)
            return _err("VALIDATION_ERROR", "page_id must be a positive integer.", http_status=400)

    # ---- resolve article ----
    articles = _load("articles.json")

    def _norm_title(s):
        s = s.strip().replace("_", " ")
        s = " ".join(s.split())
        return s.lower()

    matches = []
    if article_id is not None:
        matches = [a for a in articles if isinstance(a, dict) and a.get("id") == article_id]
    else:
        if title is not None:
            nt = _norm_title(title)
            matches = [a for a in articles if isinstance(a, dict) and a.get("language_code") == language_code and a.get("normalized_title") == nt]
        elif page_id is not None:
            matches = [a for a in articles if isinstance(a, dict) and a.get("language_code") == language_code and a.get("page_id") == page_id]

    if len(matches) == 0:
        latency_ms = int((time.time() - t0) * 1000)
        _log({"article_id": article_id, "title": title, "page_id": page_id, "language_code": language_code, "format": format, "force_refresh": force_refresh}, 404, False, None, None, latency_ms)
        return _err("NOT_FOUND", "Article not found.", http_status=404)

    if len(matches) > 1:
        latency_ms = int((time.time() - t0) * 1000)
        _log({"article_id": article_id, "title": title, "page_id": page_id, "language_code": language_code, "format": format, "force_refresh": force_refresh}, 500, False, None, "DATA_INTEGRITY_VIOLATION", latency_ms)
        return _err("CONFLICT", "Multiple articles matched the identifier due to data integrity violation.", http_status=500, error_code="DATA_INTEGRITY_VIOLATION")

    art = matches[0]
    matched_id = art.get("id")

    if art.get("status") in ("deleted", "missing"):
        latency_ms = int((time.time() - t0) * 1000)
        _log({"article_id": article_id, "title": title, "page_id": page_id, "language_code": language_code, "format": format, "force_refresh": force_refresh}, 404, False, matched_id, None, latency_ms)
        return _err("NOT_FOUND", "Article is not available.", http_status=404)

    # ---- cache TTL/refresh (simulated upstream fetch) ----
    TTL_SECONDS = 86400  # configured TTL (service default)
    cache_hit = False

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    fetched_at = _parse_dt(art.get("content_fetched_at"))
    fresh = fetched_at is not None and (now_dt - fetched_at).total_seconds() <= TTL_SECONDS
    need_refresh = force_refresh or not fresh or (art.get("extract_html") is None and art.get("extract_text") is None)

    if not need_refresh:
        cache_hit = True
    else:
        # mutate article cache fields
        title_for_content = art.get("title") or title or ""
        base = f"Cached snapshot for {title_for_content} ({art.get('language_code')}) at {now}"
        if format in ("html", "both"):
            art["extract_html"] = f"<p>{base}</p>"
        if format in ("text", "both"):
            art["extract_text"] = base
        art["content_fetched_at"] = now
        # content_revision_id may be updated "when available" - simulate deterministic revision
        try:
            rev = int(hashlib.sha256((matched_id + now).encode("utf-8")).hexdigest()[:8], 16)
        except Exception:
            rev = None
        art["content_revision_id"] = rev
        art["updated_at"] = now

        # persist mutation (NO SUCCESS WITHOUT EFFECT already satisfied)
        for i, a in enumerate(articles):
            if isinstance(a, dict) and a.get("id") == matched_id:
                articles[i] = art
                break
        _save("articles.json", articles)

    body = {
        "http_status": 200,
        "article": {
            "id": art.get("id"),
            "language_code": art.get("language_code"),
            "page_id": art.get("page_id"),
            "title": art.get("title"),
            "wikipedia_url": art.get("wikipedia_url"),
            "status": art.get("status"),
            "content_revision_id": art.get("content_revision_id"),
            "content_fetched_at": art.get("content_fetched_at"),
        }
    }
    if format in ("html", "both"):
        body["html"] = art.get("extract_html")
    if format in ("text", "both"):
        body["text"] = art.get("extract_text")

    latency_ms = int((time.time() - t0) * 1000)
    _log({"article_id": article_id, "title": title, "page_id": page_id, "language_code": language_code, "format": format, "force_refresh": force_refresh}, 200, cache_hit, matched_id, None, latency_ms)
    return body

def get_summary(language_code, article_id=None, title=None, page_id=None, force_refresh=None, **_extra):
    import json, os, datetime, time, base64, hashlib, re
