        n = 0
        for r in req_logs:
            if not isinstance(r, dict):
                continue
            if r.get("client_id") != cid:
                continue
            ts = r.get("created_at")
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
