        row = {
            "id": rid,
            "client_id": client_id,
            "tool_name": "get_summary",
            "input": input_obj if isinstance(input_obj, dict) else {},
            "matched_article_id": matched_article_id,
            "http_status": int(http_status),
            "cache_hit": bool(cache_hit),
            "latency_ms": int(max(0, min(600000, latency_ms))),
            "error_code": error_code,
            "created_at": now,
            "updated_at": now,
        }
        req_logs.append(row)
        _save("request_logs.json", req_logs)

    if client and isinstance(client.get("rate_limit_per_minute"), int):
        if _count_last_minute(client_id) >= client["rate_limit_per_minute"]:
            latency_ms = int((time.time() - t0) * 1000)
            _log({"article_id": article_id, "title": title, "page_id": page_id, "language_code": language_code, "force_refresh": force_refresh}, 429, False, None, "RATE_LIMITED", latency_ms)
            return _err("RATE_LIMIT", "Rate limit exceeded.", http_status=429)

    if not isinstance(language_code, str) or not (2 <= len(language_code) <= 12):
        latency_ms = int((time.time() - t0) * 1000)
        _log({"article_id": article_id, "title": title, "page_id": page_id, "language_code": language_code, "force_refresh": force_refresh}, 400, False, None, "VALIDATION_ERROR", latency_ms)
        return _err("VALIDATION_ERROR", "language_code must be a string of length 2–12.", http_status=400)

    if force_refresh is None:
        force_refresh = False
    if not isinstance(force_refresh, bool):
        latency_ms = int((time.time() - t0) * 1000)
        _log({"article_id": article_id, "title": title, "page_id": page_id, "language_code": language_code, "force_refresh": force_refresh}, 400, False, None, "VALIDATION_ERROR", latency_ms)
        return _err("VALIDATION_ERROR", "force_refresh must be a boolean.", http_status=400)

    if article_id is not None:
        if not isinstance(article_id, str) or not re.match(r"^wik_art_[0-9A-HJKMNP-TV-Z]{10,}$", article_id):
            latency_ms = int((time.time() - t0) * 1000)
            _log({"article_id": article_id, "title": title, "page_id": page_id, "language_code": language_code, "force_refresh": force_refresh}, 400, False, None, "VALIDATION_ERROR", latency_ms)
            return _err("VALIDATION_ERROR", "article_id does not match expected pattern.", http_status=400)

    if article_id is None:
        if title is None and page_id is None:
            latency_ms = int((time.time() - t0) * 1000)
            _log({"article_id": article_id, "title": title, "page_id": page_id, "language_code": language_code, "force_refresh": force_refresh}, 400, False, None, "VALIDATION_ERROR", latency_ms)
            return _err("VALIDATION_ERROR", "Provide article_id or (title or page_id) with language_code.", http_status=400)
        if title is not None and (not isinstance(title, str) or not title.strip()):
            latency_ms = int((time.time() - t0) * 1000)
            _log({"article_id": article_id, "title": title, "page_id": page_id, "language_code": language_code, "force_refresh": force_refresh}, 400, False, None, "VALIDATION_ERROR", latency_ms)
            return _err("VALIDATION_ERROR", "title must be a non-empty string.", http_status=400)
        if page_id is not None and (not isinstance(page_id, int) or page_id <= 0):
            latency_ms = int((time.time() - t0) * 1000)
            _log({"article_id": article_id, "title": title, "page_id": page_id, "language_code": language_code, "force_refresh": force_refresh}, 400, False, None, "VALIDATION_ERROR", latency_ms)
            return _err("VALIDATION_ERROR", "page_id must be a positive integer.", http_status=400)

    articles = _load("articles.json")

    def _norm_title(s):
        s = s.strip().replace("_", " ")
        s = " ".join(s.split())
        return s.lower()

    matches = []
    if article_id is not None:
        matches = [a for a in articles if isinstance(a, dict) and a.get("id") == article_id]
    else:
        if title is not None:
            nt = _norm_title(title)
            matches = [a for a in articles if isinstance(a, dict) and a.get("language_code") == language_code and a.get("normalized_title") == nt]
        else:
            matches = [a for a in articles if isinstance(a, dict) and a.get("language_code") == language_code and a.get("page_id") == page_id]

    if len(matches) == 0:
        latency_ms = int((time.time() - t0) * 1000)
        _log({"article_id": article_id, "title": title, "page_id": page_id, "language_code": language_code, "force_refresh": force_refresh}, 404, False, None, None, latency_ms)
        return _err("NOT_FOUND", "Article not found.", http_status=404)

    if len(matches) > 1:
        latency_ms = int((time.time() - t0) * 1000)
        _log({"article_id": article_id, "title": title, "page_id": page_id, "language_code": language_code, "force_refresh": force_refresh}, 500, False, None, "DATA_INTEGRITY_VIOLATION", latency_ms)
        return _err("CONFLICT", "Multiple articles matched the identifier due to data integrity violation.", http_status=500, error_code="DATA_INTEGRITY_VIOLATION")

    art = matches[0]
    matched_id = art.get("id")

    if art.get("status") in ("deleted", "missing"):
        latency_ms = int((time.time() - t0) * 1000)
        _log({"article_id": article_id, "title": title, "page_id": page_id, "language_code": language_code, "force_refresh": force_refresh}, 404, False, matched_id, None, latency_ms)
        return _err("NOT_FOUND", "Article is not available.", http_status=404)

    TTL_SECONDS = 3600  # configured TTL (service default)
    cache_hit = False

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    fetched_at = _parse_dt(art.get("summary_fetched_at"))
    fresh = fetched_at is not None and (now_dt - fetched_at).total_seconds() <= TTL_SECONDS
    need_refresh = force_refresh or not fresh or (art.get("summary_text") is None)

    if not need_refresh:
        cache_hit = True
    else:
        title_for_summary = art.get("title") or title or ""
        art["summary_text"] = f"Lead summary for {title_for_summary} ({art.get('language_code')}) as of {now}."
        art["summary_fetched_at"] = now
        # update revision id when available
        try:
            rev = int(hashlib.sha256((matched_id + "summary" + now).encode("utf-8")).hexdigest()[:8], 16)
        except Exception:
            rev = art.get("content_revision_id")
        art["content_revision_id"] = rev
        art["updated_at"] = now

        for i, a in enumerate(articles):
            if isinstance(a, dict) and a.get("id") == matched_id:
                articles[i] = art
                break
        _save("articles.json", articles)

    latency_ms = int((time.time() - t0) * 1000)
    _log({"article_id": article_id, "title": title, "page_id": page_id, "language_code": language_code, "force_refresh": force_refresh}, 200, cache_hit, matched_id, None, latency_ms)
    return {
        "http_status": 200,
        "article": {
            "id": art.get("id"),
            "language_code": art.get("language_code"),
            "page_id": art.get("page_id"),
            "title": art.get("title"),
            "wikipedia_url": art.get("wikipedia_url"),
            "status": art.get("status"),
            "content_revision_id": art.get("content_revision_id"),
            "summary_fetched_at": art.get("summary_fetched_at"),
        },
        "summary": art.get("summary_text"),
    }

def get_related_topics(language_code, article_id=None, title=None, page_id=None, limit=None, cursor=None, edge_type=None, min_weight=None, status=None, force_refresh=None, **_extra):
    import json, os, datetime, time, secrets, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0475000" if __import__("os").path.isdir("./environment_mix/0475000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        s = "".join(alphabet[secrets.randbelow(len(alphabet))] for _ in range(16))
        return f"{prefix}_{s}"

    def _parse_iso(ts):
        if not isinstance(ts, str) or not ts:
            return None
        try:
            return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    # ---- ambient auth: pick any active client that can serve call (rate limit not exceeded) ----
    clients = _load("api_clients.json")
    req_logs = _load("request_logs.json")

    def _count_last_minute(cid):
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        n = 0
        for r in req_logs:
            if not isinstance(r, dict):
                continue
            if r.get("client_id") != cid:
                continue
            dt = _parse_iso(r.get("created_at"))
            if dt is None:
                continue
            if dt >= cutoff:
                n += 1
        return n

    def _pick_client():
        active = [c for c in clients if isinstance(c, dict) and c.get("status") == "active" and isinstance(c.get("rate_limit_per_minute"), int)]
        # Prefer a client with available headroom; otherwise any active (we'll rate-limit below)
        best = None
        best_headroom = None
        for c in active:
            lim = c.get("rate_limit_per_minute")
            if not isinstance(lim, int) or lim < 1 or lim > 6000:
                continue
            used = _count_last_minute(c.get("id"))
            headroom = lim - used
            if best is None or headroom > best_headroom:
                best = c
                best_headroom = headroom
        return best

    client = _pick_client()
    client_id = client.get("id") if isinstance(client, dict) else None

    def _append_log(input_obj, http_status, cache_hit, matched_article_id=None, error_code=None):
        nonlocal req_logs
        latency_ms = int(max(0, (time.time() - t0) * 1000))
        entry = {
            "id": _gen_id("wik_req"),
            "client_id": client_id,
            "tool_name": "get_related_topics",
            "input": input_obj if isinstance(input_obj, dict) else {},
            "matched_article_id": matched_article_id,
            "http_status": int(http_status),
            "cache_hit": bool(cache_hit),
            "latency_ms": int(min(max(latency_ms, 0), 600000)),
            "error_code": error_code,
            "created_at": now,
            "updated_at": now,
        }
        req_logs.append(entry)
        _save("request_logs.json", req_logs)

    # ---- input validation (cursor is opaque; do not validate format) ----
    if not isinstance(language_code, str) or not (2 <= len(language_code) <= 12):
        _append_log({"language_code": language_code}, 400, False, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "language_code must be a string of length 2..12.", http_status=400)

    if limit is None:
        limit = 10
    if not isinstance(limit, int) or limit < 1 or limit > 50:
        _append_log({"language_code": language_code, "limit": limit}, 400, False, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 50.", http_status=400)

    if edge_type is None:
        edge_type = "both"
    if edge_type not in ("link", "category", "both"):
        _append_log({"language_code": language_code, "edge_type": edge_type}, 400, False, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "edge_type must be one of: link, category, both.", http_status=400)

    if status is None:
        status = "active"
    if status not in ("active", "stale", "disabled"):
        _append_log({"language_code": language_code, "status": status}, 400, False, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of: active, stale, disabled.", http_status=400)

    if min_weight is not None and not isinstance(min_weight, (int, float)):
        _append_log({"language_code": language_code, "min_weight": min_weight}, 400, False, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "min_weight must be a number when provided.", http_status=400)
    if min_weight is None:
        min_weight = 0.0

    if force_refresh is not None and not isinstance(force_refresh, bool):
        _append_log({"language_code": language_code, "force_refresh": force_refresh}, 400, False, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "force_refresh must be a boolean when provided.", http_status=400)

    # ---- rate limiting (must still log on 429) ----
    if client is None:
        # ambient auth must not refuse; if no clients exist, treat as unidentified but allow (no rate limit)
        pass
    else:
        lim = client.get("rate_limit_per_minute")
        if isinstance(lim, int) and 1 <= lim <= 6000:
            used = _count_last_minute(client_id)
            if used >= lim:
                _append_log(
                    {
                        "language_code": language_code,
                        "article_id": article_id,
                        "title": title,
                        "page_id": page_id,
                        "limit": limit,
                        "cursor": cursor,
                        "edge_type": edge_type,
                        "min_weight": min_weight,
                        "status": status,
                        "force_refresh": bool(force_refresh) if isinstance(force_refresh, bool) else False,
                    },
                    429,
                    False,
                    None,
                    "RATE_LIMITED",
                )
                return _err("RATE_LIMIT", "Rate limit exceeded.", http_status=429)

    articles = _load("articles.json")
    edges = _load("article_graph.json")
    sidx = _load("search_index.json")

    art_by_id = {a.get("id"): a for a in articles if isinstance(a, dict) and isinstance(a.get("id"), str)}
    sidx_by_article = {}
    for r in sidx:
        if not isinstance(r, dict):
            continue
        if r.get("status") != "active":
            continue
        aid = r.get("article_id")
        if isinstance(aid, str):
            sidx_by_article[aid] = r

    # ---- resolve source article ----
    matched_article_id = None
    resolved_article = None
    integrity_violation = False

    if article_id is not None:
        if not isinstance(article_id, str):
            _append_log({"language_code": language_code, "article_id": article_id}, 400, False, None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "article_id must be a string when provided.", http_status=400)
        resolved_article = art_by_id.get(article_id)
        matched_article_id = article_id
        if resolved_article is None:
            _append_log({"language_code": language_code, "article_id": article_id}, 404, False, article_id, "ARTICLE_NOT_FOUND")
            return _err("NOT_FOUND", "Article not found.", http_status=404)
    else:
        if not isinstance(title, str) and not isinstance(page_id, int):
            _append_log({"language_code": language_code, "title": title, "page_id": page_id}, 400, False, None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Provide article_id or (title or page_id) with language_code.", http_status=400)

        matches = []
        if isinstance(page_id, int):
            for a in articles:
                if not isinstance(a, dict):
                    continue
                if a.get("language_code") == language_code and a.get("page_id") == page_id:
                    matches.append(a)
        else:
            # normalize like stored normalized_title: lowercase, spaces->single space, underscores->space, strip
            norm = title.replace("_", " ").strip().lower()
            norm = re.sub(r"\s+", " ", norm)
            for a in articles:
                if not isinstance(a, dict):
                    continue
                if a.get("language_code") == language_code and a.get("normalized_title") == norm:
                    matches.append(a)

        if len(matches) == 0:
            _append_log({"language_code": language_code, "title": title, "page_id": page_id}, 404, False, None, "ARTICLE_NOT_FOUND")
            return _err("NOT_FOUND", "Article not found.", http_status=404)
        if len(matches) > 1:
            integrity_violation = True
        else:
            resolved_article = matches[0]
            matched_article_id = resolved_article.get("id")

    if integrity_violation:
        _append_log({"language_code": language_code, "title": title, "page_id": page_id}, 500, False, None, "DATA_INTEGRITY_VIOLATION")
        return _err("CONFLICT", "Multiple articles matched the lookup; data integrity violation.", http_status=500, error_code="DATA_INTEGRITY_VIOLATION")

    # enforce 404 when missing/deleted even if resolved
    if isinstance(resolved_article, dict):
        st = resolved_article.get("status")
        if st in ("deleted", "missing"):
            _append_log(
                {
                    "language_code": language_code,
                    "article_id": matched_article_id,
                    "title": title,
                    "page_id": page_id,
                },
                404,
                True,
                matched_article_id,
                "ARTICLE_NOT_FOUND",
            )
            return _err("NOT_FOUND", "Article is missing or deleted.", http_status=404)

    # ---- compute related topics ----
    allowed_edge_types = {"link", "category"} if edge_type == "both" else {edge_type}

    # force_refresh: for offline store, we can only recompute ranking from latest edges/index, no external rebuild.
    # Mark cache_hit accordingly.
    cache_hit = not bool(force_refresh)

    weights_by_target = {}
    for e in edges:
        if not isinstance(e, dict):
            continue
        if e.get("language_code") != language_code:
            continue
        if e.get("status") != status:
            continue
        if e.get("edge_type") not in allowed_edge_types:
            continue
        if e.get("from_article_id") != matched_article_id:
            continue
        w = e.get("weight")
        if not isinstance(w, (int, float)):
            continue
        if w < float(min_weight):
            continue
        to_id = e.get("to_article_id")
        if not isinstance(to_id, str) or to_id == matched_article_id:
            continue
        # foreign key integrity at read-time: skip if missing
        if to_id not in art_by_id:
            continue
        weights_by_target[to_id] = weights_by_target.get(to_id, 0.0) + float(w)

    candidates = []
    for to_id, sum_w in weights_by_target.items():
        a = art_by_id.get(to_id)
        if not isinstance(a, dict):
            continue
        if a.get("status") not in ("active", "redirect"):
            continue
        idx = sidx_by_article.get(to_id)
        pop = 0.0
        if isinstance(idx, dict) and isinstance(idx.get("popularity_score"), (int, float)):
            pop = float(idx["popularity_score"])
        candidates.append((to_id, sum_w, pop, a, idx))

    candidates.sort(key=lambda t: (t[1], t[2], (t[4] or {}).get("title") if isinstance(t[4], dict) else t[3].get("title")), reverse=True)

    # pagination cursor: opaque string; interpret as an offset if it looks like "o:<int>", else treat as a last_seen_article_id
    start = 0
    if isinstance(cursor, str) and cursor:
        if cursor.startswith("o:"):
            try:
                start = max(0, int(cursor[2:]))
            except Exception:
                start = 0
        else:
            # find position after the article_id
            for i, (to_id, *_rest) in enumerate(candidates):
                if to_id == cursor:
                    start = i + 1
                    break

    page = candidates[start:start + limit]
    next_cursor = None
    has_more = (start + limit) < len(candidates)
    if has_more:
        # issue offset cursor
        next_cursor = f"o:{start + limit}"

    items = []
    for to_id, sum_w, pop, a, idx in page:
        items.append({
            "article_id": to_id,
            "language_code": a.get("language_code"),
            "page_id": a.get("page_id"),
            "title": a.get("title"),
            "wikipedia_url": a.get("wikipedia_url"),
            "status": a.get("status"),
            "score": {"sum_weight": sum_w, "popularity_score": pop},
            "edge_status": status,
            "edge_types_used": list(sorted(allowed_edge_types)),
        })

    _append_log(
        {
            "language_code": language_code,
            "article_id": article_id,
            "title": title,
            "page_id": page_id,
            "limit": limit,
            "cursor": cursor,
            "edge_type": edge_type,
            "min_weight": min_weight,
            "status": status,
            "force_refresh": bool(force_refresh) if isinstance(force_refresh, bool) else False,
        },
        200,
        cache_hit,
        matched_article_id,
        None,
    )
    return {
        "tool_name": "get_related_topics",
        "matched_article_id": matched_article_id,
        "data": items,
        "pagination": {"total": len(candidates), "limit": limit, "has_more": has_more, "next_cursor": next_cursor},
        "http_status": 200,
        "cache_hit": cache_hit,
    }

def whoami(api_key, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0475000" if __import__("os").path.isdir("./environment_mix/0475000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    _TOOL = "whoami"
    t0 = time.time()

    def _log_request(client_id, input_obj, http_status, cache_hit, error_code=None, matched_article_id=None):
        logs = _load("request_logs.json")
        ts = _now_iso()
        rid = "req_" + datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f")
        latency_ms = int(max(0, (time.time() - t0) * 1000))
        row = {
            "id": rid,
            "client_id": client_id,
            "tool_name": _TOOL,
            "input": input_obj if isinstance(input_obj, dict) else {},
            "matched_article_id": matched_article_id,
            "http_status": int(http_status),
            "cache_hit": bool(cache_hit),
            "latency_ms": int(max(0, min(600000, latency_ms))),
            "error_code": error_code,
            "created_at": ts,
            "updated_at": ts,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    # Validate
    if not isinstance(api_key, str) or not api_key.strip():
        _log_request(None, {"api_key_present": bool(api_key)}, 400, False, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")

    clients = _load("api_clients.json")

    # Authenticate: match by id OR client-visible api_key_hash field (which stores key value in this datastore)
    client = None
    for c in clients:
        if c.get("id") == api_key or c.get("api_key_hash") == api_key:
            client = c
            break

    if not client:
        _log_request(None, {"api_key_present": True}, 401, False, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid or missing credential")

    if client.get("status") == "revoked":
        _log_request(client.get("id"), {"client_id": client.get("id")}, 403, False, error_code="FORBIDDEN_REVOKED")
        return _err("UNAUTHORIZED", "Client is revoked")

    # Rate limit / consumption for active window (rolling last 60s)
    rate_limit = client.get("rate_limit_per_minute")
    if not isinstance(rate_limit, int):
        rate_limit = 60
    try:
        rate_limit = max(1, min(6000, int(rate_limit)))
    except Exception:
        rate_limit = 60

    logs = _load("request_logs.json")
    now = datetime.datetime.now(datetime.timezone.utc)
    window_start = now - datetime.timedelta(seconds=60)

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    used = 0
    for r in logs:
        if r.get("client_id") != client.get("id"):
            continue
        dt = _parse_dt(r.get("created_at"))
        if dt is None:
            continue
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        if dt >= window_start and dt <= now:
            used += 1

    remaining = max(0, rate_limit - used)

    _log_request(client.get("id"), {"client_id": client.get("id")}, 200, True, error_code=None)

    # Scopes are not modeled in schema; return empty list.
    return {
        "client": {
            "id": client.get("id"),
            "display_name": client.get("display_name"),
            "status": client.get("status"),
            "scopes": [],
        },
        "rate_limit": {
