            "tool_name": _TOOL,
            "input": input_obj if isinstance(input_obj, dict) else {},
            "matched_article_id": matched_article_id,
            "http_status": int(http_status),
            "cache_hit": bool(cache_hit),
            "latency_ms": int(max(0, min(600000, latency_ms))),
            "error_code": error_code,
            "created_at": ts,
            "updated_at": ts,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    # Validate api_key
    if not isinstance(api_key, str) or not api_key.strip():
        _log_request(None, {"api_key_present": bool(api_key)}, 400, False, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")

    clients = _load("api_clients.json")
    client = None
    for c in clients:
        if c.get("id") == api_key or c.get("api_key_hash") == api_key:
            client = c
            break
    if not client:
        _log_request(None, {"api_key_present": True}, 401, False, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid or missing credential")

    if client.get("status") in ("suspended", "revoked"):
        _log_request(client.get("id"), {"client_id": client.get("id")}, 403, False, error_code="FORBIDDEN")
        return _err("UNAUTHORIZED", "Client is suspended or revoked")

    # Enforce rate limit (rolling 60s), still log on 429
    rate_limit = client.get("rate_limit_per_minute")
    if not isinstance(rate_limit, int):
        rate_limit = 60
    try:
        rate_limit = max(1, min(6000, int(rate_limit)))
    except Exception:
        rate_limit = 60

    logs = _load("request_logs.json")
    now = datetime.datetime.now(datetime.timezone.utc)
    window_start = now - datetime.timedelta(seconds=60)
    used = 0
    for r in logs:
        if r.get("client_id") != client.get("id"):
            continue
        dt = _parse_dt(r.get("created_at"))
        if dt is None:
            continue
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        if dt >= window_start and dt <= now:
            used += 1
    if used >= rate_limit:
        _log_request(client.get("id"), {"language_code": language_code, "status": status, "page_id": page_id, "title_prefix": title_prefix, "limit": limit, "cursor": cursor}, 429, False, error_code="RATE_LIMITED")
        return _err("RATE_LIMIT", "Rate limit exceeded", retry_after_seconds=60)

    # Validate filters
    eff_lang = language_code if language_code is not None else "en"
    if not isinstance(eff_lang, str) or not (2 <= len(eff_lang) <= 12):
        _log_request(client.get("id"), {"language_code": language_code}, 400, False, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "language_code must be a string length 2..12")

    allowed_status = {"active", "missing", "redirect", "deleted", "error"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _log_request(client.get("id"), {"status": status}, 400, False, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status must be one of: active, missing, redirect, deleted, error")

    if page_id is not None:
        if not isinstance(page_id, int) or page_id <= 0:
            _log_request(client.get("id"), {"page_id": page_id}, 400, False, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "page_id must be a positive integer")

    if title_prefix is not None:
        if not isinstance(title_prefix, str):
            _log_request(client.get("id"), {"title_prefix": title_prefix}, 400, False, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "title_prefix must be a string")

    if limit is None:
        eff_limit = 50
    else:
        if not isinstance(limit, int) or not (1 <= limit <= 100):
            _log_request(client.get("id"), {"limit": limit}, 400, False, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be an integer 1..100")
        eff_limit = limit

    start = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            _log_request(client.get("id"), {"cursor": cursor}, 400, False, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            if not raw.startswith("v1:"):
                raise ValueError("bad version")
            start = int(raw.split(":", 1)[1])
            if start < 0:
                raise ValueError("neg")
        except Exception:
            _log_request(client.get("id"), {"cursor": cursor}, 400, False, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is malformed")

    articles = _load("articles.json")

    def _norm(s):
        return (s or "").strip().lower()

    tp = _norm(title_prefix) if title_prefix is not None else None

    filtered = []
    for a in articles:
        if a.get("language_code") != eff_lang:
            continue
        if status is not None and a.get("status") != status:
            continue
        if page_id is not None and a.get("page_id") != page_id:
            continue
        if tp is not None:
            nt = _norm(a.get("normalized_title"))
            if not nt.startswith(tp):
                continue
        filtered.append(a)

    # Stable sort: normalized_title then page_id then id
    def _sort_key(a):
        nt = a.get("normalized_title") or ""
        pid = a.get("page_id") if isinstance(a.get("page_id"), int) else 0
        aid = a.get("id") or ""
        return (nt.lower(), pid, aid)

    filtered.sort(key=_sort_key)

    total = len(filtered)
    page = filtered[start:start + eff_limit]
    next_start = start + len(page)
    has_more = next_start < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"v1:{next_start}".encode("utf-8")).decode("utf-8")

    _log_request(
        client.get("id"),
        {"language_code": eff_lang, "status": status, "page_id": page_id, "title_prefix": title_prefix, "limit": eff_limit, "cursor": cursor},
        200,
        True,
        error_code=None
    )

    return {
        "data": page,
        "meta": {
            "language_code": eff_lang,
            "total": total,
            "limit": eff_limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }

