def upsert_article(api_key, article_id=None, language_code=None, page_id=None, title=None, normalized_title=None, wikipedia_url=None, extract_html=None, extract_text=None, summary_text=None, content_revision_id=None, content_fetched_at=None, summary_fetched_at=None, status=None, **_extra):
