            "cache_hit": bool(cache_hit),
            "latency_ms": int(max(0, min(600000, latency_ms))),
            "error_code": error_code,
            "created_at": ts,
            "updated_at": ts,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _ulid_like():
        # Not a strict ULID implementation; generates allowed Crockford base32 without I,L,O,U.
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        n = 16
        return "wik_art_" + "".join(random.choice(alphabet) for _ in range(n))

    # Validate api_key
    if not isinstance(api_key, str) or not api_key.strip():
        _log_request(None, {"api_key_present": bool(api_key)}, 400, False, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")

    clients = _load("api_clients.json")
    client = None
    for c in clients:
        if c.get("id") == api_key or c.get("api_key_hash") == api_key:
            client = c
            break
    if not client:
        _log_request(None, {"api_key_present": True}, 401, False, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid or missing credential")

    if client.get("status") in ("suspended", "revoked"):
        _log_request(client.get("id"), {"client_id": client.get("id")}, 403, False, error_code="FORBIDDEN")
        return _err("UNAUTHORIZED", "Client is suspended or revoked")

    # Rate limit
    rate_limit = client.get("rate_limit_per_minute")
    if not isinstance(rate_limit, int):
        rate_limit = 60
    try:
        rate_limit = max(1, min(6000, int(rate_limit)))
    except Exception:
        rate_limit = 60

    logs = _load("request_logs.json")
    now = datetime.datetime.now(datetime.timezone.utc)
    window_start = now - datetime.timedelta(seconds=60)
    used = 0
    for r in logs:
        if r.get("client_id") != client.get("id"):
            continue
        dt = _parse_dt(r.get("created_at"))
        if dt is None:
            continue
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        if dt >= window_start and dt <= now:
            used += 1
    if used >= rate_limit:
        _log_request(client.get("id"), {"article_id": article_id, "language_code": language_code}, 429, False, error_code="RATE_LIMITED")
        return _err("RATE_LIMIT", "Rate limit exceeded", retry_after_seconds=60)

    # Validate required language_code
    if not isinstance(language_code, str) or not (2 <= len(language_code) <= 12):
        _log_request(client.get("id"), {"language_code": language_code}, 400, False, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "language_code must be a string length 2..12")

    # Validate optional article_id format
    if article_id is not None:
        if not isinstance(article_id, str) or not re.match(r"^wik_art_[0-9A-HJKMNP-TV-Z]{10,}$", article_id):
            _log_request(client.get("id"), {"article_id": article_id}, 400, False, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "article_id is malformed")

    # Validate other fields
    if page_id is not None and (not isinstance(page_id, int) or page_id <= 0):
        _log_request(client.get("id"), {"page_id": page_id}, 400, False, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "page_id must be a positive integer")

    if title is not None and not isinstance(title, str):
        _log_request(client.get("id"), {"title": title}, 400, False, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "title must be a string")

    if normalized_title is not None and not isinstance(normalized_title, str):
        _log_request(client.get("id"), {"normalized_title": normalized_title}, 400, False, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "normalized_title must be a string")

    if wikipedia_url is not None:
        if not isinstance(wikipedia_url, str) or not wikipedia_url.startswith("http"):
            _log_request(client.get("id"), {"wikipedia_url": wikipedia_url}, 400, False, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "wikipedia_url must be a string starting with 'http'")

    if extract_html is not None and not isinstance(extract_html, str):
        _log_request(client.get("id"), {"extract_html": "non-string"}, 400, False, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "extract_html must be a string")

    if extract_text is not None and not isinstance(extract_text, str):
        _log_request(client.get("id"), {"extract_text": "non-string"}, 400, False, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "extract_text must be a string")

    if summary_text is not None and not isinstance(summary_text, str):
        _log_request(client.get("id"), {"summary_text": "non-string"}, 400, False, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "summary_text must be a string")

    if content_revision_id is not None and not isinstance(content_revision_id, int):
        _log_request(client.get("id"), {"content_revision_id": content_revision_id}, 400, False, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "content_revision_id must be an integer")

    cfa = _parse_dt(content_fetched_at)
