        _log_request(client.get("id"), {"content_fetched_at": content_fetched_at}, 400, False, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "content_fetched_at must be RFC3339 date-time string")

    sfa = _parse_dt(summary_fetched_at)
    if summary_fetched_at is not None and sfa is None:
        _log_request(client.get("id"), {"summary_fetched_at": summary_fetched_at}, 400, False, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "summary_fetched_at must be RFC3339 date-time string")

    allowed_status = {"active", "missing", "redirect", "deleted", "error"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        _log_request(client.get("id"), {"status": status}, 400, False, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of: active, missing, redirect, deleted, error")

    # Load existing
    articles = _load("articles.json")
    existing = None
    existing_idx = None
    if article_id is not None:
        for i, a in enumerate(articles):
            if a.get("id") == article_id:
                existing = a
                existing_idx = i
                break

    # If creating and no article_id, generate unique
    if existing is None and article_id is None:
        existing_ids = {a.get("id") for a in articles if isinstance(a.get("id"), str)}
        new_id = _ulid_like()
        tries = 0
        while new_id in existing_ids and tries < 50:
            new_id = _ulid_like()
            tries += 1
        article_id = new_id

    # Enforce required fields for creation to satisfy constraints
    creating = existing is None
    if creating:
        missing_fields = []
        if page_id is None:
            missing_fields.append("page_id")
        if title is None:
            missing_fields.append("title")
        if normalized_title is None:
            missing_fields.append("normalized_title")
        if wikipedia_url is None:
            missing_fields.append("wikipedia_url")
        if status is None:
            missing_fields.append("status")
        if missing_fields:
            _log_request(client.get("id"), {"article_id": article_id, "missing_fields": missing_fields}, 400, False, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Missing required fields for create", missing_fields=missing_fields)

    # Enforce uniqueness constraints on (language_code,page_id) and (language_code,normalized_title)
    def _conflict_row(match):
        return _err("CONFLICT", "Uniqueness constraint violated", conflict=match)

    for a in articles:
        if existing is not None and a.get("id") == existing.get("id"):
            continue
        if a.get("language_code") == language_code and page_id is not None and a.get("page_id") == page_id:
            _log_request(client.get("id"), {"article_id": article_id, "language_code": language_code, "page_id": page_id}, 409, False, error_code="CONFLICT")
            return _conflict_row({"unique": "language_code,page_id", "existing_article_id": a.get("id")})
        if a.get("language_code") == language_code and normalized_title is not None and a.get("normalized_title") == normalized_title:
            _log_request(client.get("id"), {"article_id": article_id, "language_code": language_code, "normalized_title": normalized_title}, 409, False, error_code="CONFLICT")
            return _conflict_row({"unique": "language_code,normalized_title", "existing_article_id": a.get("id")})

    # Enforce status transitions
    transitions = {
        "missing": {"active", "redirect", "deleted", "error"},
        "error": {"active", "missing", "redirect", "deleted"},
        "redirect": {"active", "missing", "deleted", "error"},
        "active": {"redirect", "deleted", "error"},
        "deleted": {"missing", "error"},
    }

    ts = _now_iso()
    if creating:
        # Initial status must be one of lifecycle values; allow any as initial
        new_status = status
    else:
        new_status = existing.get("status")
        if status is not None and status != existing.get("status"):
            cur = existing.get("status")
            if cur not in transitions or status not in transitions[cur]:
                _log_request(client.get("id"), {"article_id": article_id, "from": cur, "to": status}, 409, False, error_code="INVALID_TRANSITION")
                return _err("INVALID_TRANSITION", "Illegal status transition", from_status=cur, to_status=status)
            new_status = status

    if creating:
        row = {
            "id": article_id,
            "language_code": language_code,
            "page_id": page_id,
            "title": title,
            "normalized_title": normalized_title,
            "wikipedia_url": wikipedia_url,
            "extract_html": extract_html if extract_html is not None else None,
            "extract_text": extract_text if extract_text is not None else None,
            "summary_text": summary_text if summary_text is not None else None,
            "content_revision_id": content_revision_id if content_revision_id is not None else None,
            "content_fetched_at": content_fetched_at if content_fetched_at is not None else None,
            "summary_fetched_at": summary_fetched_at if summary_fetched_at is not None else None,
            "status": new_status,
            "created_at": ts,
            "updated_at": ts,
        }
        articles.append(row)
        _save("articles.json", articles)
        _log_request(client.get("id"), {"article_id": article_id, "op": "create"}, 200, False, error_code=None, matched_article_id=article_id)
        return {"data": row, "meta": {"created": True}}
    else:
        # Update existing, only provided fields
        updated = dict(existing)
        updated["language_code"] = language_code  # required; treat as authoritative for partitioning
        if page_id is not None:
            updated["page_id"] = page_id
        if title is not None:
            updated["title"] = title
        if normalized_title is not None:
            updated["normalized_title"] = normalized_title
        if wikipedia_url is not None:
            updated["wikipedia_url"] = wikipedia_url
        if extract_html is not None:
            updated["extract_html"] = extract_html
        if extract_text is not None:
            updated["extract_text"] = extract_text
        if summary_text is not None:
            updated["summary_text"] = summary_text
        if content_revision_id is not None:
            updated["content_revision_id"] = content_revision_id
        if content_fetched_at is not None:
            updated["content_fetched_at"] = content_fetched_at
        if summary_fetched_at is not None:
            updated["summary_fetched_at"] = summary_fetched_at
        if status is not None:
            updated["status"] = new_status
        updated["updated_at"] = ts

        # Re-check constraints post-update
        if not isinstance(updated.get("page_id"), int) or updated["page_id"] <= 0:
            _log_request(client.get("id"), {"article_id": article_id}, 400, False, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "page_id must be a positive integer")
        lc = updated.get("language_code")
        if not isinstance(lc, str) or not (2 <= len(lc) <= 12):
            _log_request(client.get("id"), {"article_id": article_id}, 400, False, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "language_code must be a string length 2..12")
        url = updated.get("wikipedia_url")
        if not isinstance(url, str) or not url.startswith("http"):
            _log_request(client.get("id"), {"article_id": article_id}, 400, False, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "wikipedia_url must start with http")

        articles[existing_idx] = updated
        _save("articles.json", articles)

        _log_request(client.get("id"), {"article_id": article_id, "op": "update"}, 200, False, error_code=None, matched_article_id=article_id)
        return {"data": updated, "meta": {"created": False}}

def upsert_search_index_entry(api_key, language_code, article_id, title, normalized_title, id=None, keywords=None, popularity_score=None, status=None, **_extra):
    import json, os, datetime, time, secrets, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0475000" if __import__("os").path.isdir("./environment_mix/0475000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        s = "".join(alphabet[secrets.randbelow(len(alphabet))] for _ in range(16))
        return f"{prefix}_{s}"

    def _append_log(client_id, input_obj, matched_article_id, http_status, cache_hit, error_code):
        logs = _load("request_logs.json")
        latency_ms = int(max(0, (time.time() - t0) * 1000))
        logs.append({
            "id": _gen_id("wik_req"),
            "client_id": client_id,
            "tool_name": "search_wikipedia",  # maintenance operation; closest public tool for logging is search_wikipedia
            "input": input_obj if isinstance(input_obj, dict) else {},
            "matched_article_id": matched_article_id,
            "http_status": int(http_status),
            "cache_hit": bool(cache_hit),
            "latency_ms": int(min(max(latency_ms, 0), 600000)),
            "error_code": error_code,
            "created_at": now,
            "updated_at": now,
        })
        _save("request_logs.json", logs)

    # ---- auth (match by client-visible value: id or api_key_hash) ----
    if not isinstance(api_key, str) or not api_key:
        _append_log(None, {"language_code": language_code}, None, 401, False, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Missing or invalid api_key.", http_status=401)

    clients = _load("api_clients.json")
    client = None
    for c in clients:
        if not isinstance(c, dict):
            continue
        if api_key == c.get("id") or api_key == c.get("api_key_hash"):
            client = c
            break
    if client is None:
        _append_log(None, {"language_code": language_code}, None, 401, False, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Missing or invalid api_key.", http_status=401)

    if client.get("status") != "active":
        _append_log(client.get("id"), {"language_code": language_code}, None, 401, False, "FORBIDDEN")
        return _err("UNAUTHORIZED", "Client is not allowed (suspended/revoked).", http_status=401)

    # ---- rate limit ----
    limit_per_min = client.get("rate_limit_per_minute")
    if not isinstance(limit_per_min, int) or limit_per_min < 1 or limit_per_min > 6000:
        _append_log(client.get("id"), {"language_code": language_code}, None, 500, False, "CLIENT_RATE_LIMIT_MISCONFIGURED")
        return _err("CONFLICT", "Client rate limit misconfigured.", http_status=500)

    logs = _load("request_logs.json")
    cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
    used = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("client_id") != client.get("id"):
            continue
        dt = None
        ts = r.get("created_at")
        if isinstance(ts, str):
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                dt = None
        if dt is not None and dt >= cutoff:
            used += 1
    if used >= limit_per_min:
        _append_log(client.get("id"), {"language_code": language_code, "article_id": article_id}, None, 429, False, "RATE_LIMITED")
        return _err("RATE_LIMIT", "Rate limit exceeded.", http_status=429)

    # ---- validate inputs ----
    if not isinstance(language_code, str) or not (2 <= len(language_code) <= 12):
        _append_log(client.get("id"), {"language_code": language_code}, None, 400, False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "language_code must be a string of length 2..12.", http_status=400)

    art_pat = re.compile(r"^wik_art_[0-9A-HJKMNP-TV-Z]{10,}$")
    if not isinstance(article_id, str) or not art_pat.match(article_id):
        _append_log(client.get("id"), {"article_id": article_id}, None, 400, False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "article_id is malformed.", http_status=400)

    if not isinstance(title, str) or not title.strip():
        _append_log(client.get("id"), {"title": title}, article_id, 400, False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "title must be a non-empty string.", http_status=400)

    if not isinstance(normalized_title, str) or not normalized_title.strip():
        _append_log(client.get("id"), {"normalized_title": normalized_title}, article_id, 400, False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "normalized_title must be a non-empty string.", http_status=400)

    if keywords is None:
        keywords = []
    if not isinstance(keywords, list) or any(not isinstance(k, str) for k in keywords):
        _append_log(client.get("id"), {"keywords": keywords}, article_id, 400, False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "keywords must be an array of strings.", http_status=400)

    if popularity_score is None:
        popularity_score = 0.0
    if not isinstance(popularity_score, (int, float)) or popularity_score < 0:
        _append_log(client.get("id"), {"popularity_score": popularity_score}, article_id, 400, False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "popularity_score must be a non-negative number.", http_status=400)

    if status is None:
        status = "active"
    if status not in ("active", "stale", "disabled"):
        _append_log(client.get("id"), {"status": status}, article_id, 400, False, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of: active, stale, disabled.", http_status=400)

    # id is optional; if provided and not matching pattern, ignore by treating as "create new" only if it's not a known id
    sidx_pat = re.compile(r"^wik_sidx_[0-9A-HJKMNP-TV-Z]{10,}$")
    if id is not None and (not isinstance(id, str) or not sidx_pat.match(id)):
        # Accept request by generating a new id instead of failing (parameter is optional and vendor allows omit)
        id = None

    # ---- foreign key integrity ----
    articles = _load("articles.json")
    if not any(isinstance(a, dict) and a.get("id") == article_id for a in articles):
        _append_log(client.get("id"), {"article_id": article_id}, article_id, 404, False, "ARTICLE_NOT_FOUND")
        return _err("NOT_FOUND", "Referenced article_id does not exist.", http_status=404)

    rows = _load("search_index.json")
    existing = None
    if id is not None:
        for r in rows:
            if isinstance(r, dict) and r.get("id") == id:
                existing = r
                break
    else:
        # if unique(language_code, article_id) exists, update that row (idempotent upsert)
        for r in rows:
            if isinstance(r, dict) and r.get("language_code") == language_code and r.get("article_id") == article_id:
                existing = r
                id = r.get("id")
                break

    lifecycle = {
        "active": ["stale", "disabled"],
        "stale": ["active", "disabled"],
        "disabled": ["active"],
    }

    # ---- uniqueness constraints ----
    # unique(language_code, article_id)
    for r in rows:
        if not isinstance(r, dict):
            continue
        if existing is not None and r is existing:
            continue
        if r.get("language_code") == language_code and r.get("article_id") == article_id:
            _append_log(client.get("id"), {"language_code": language_code, "article_id": article_id}, article_id, 409, False, "UNIQUE_VIOLATION")
            return _err("CONFLICT", "unique(language_code, article_id) violated.", http_status=409)

    # ---- mutate ----
    created = False
    if existing is None:
        created = True
        new_id = id or _gen_id("wik_sidx")
        # ensure id uniqueness
        if any(isinstance(r, dict) and r.get("id") == new_id for r in rows):
            _append_log(client.get("id"), {"id": new_id}, article_id, 409, False, "ID_CONFLICT")
            return _err("CONFLICT", "id already exists.", http_status=409)

        row = {
            "id": new_id,
            "language_code": language_code,
            "article_id": article_id,
            "title": title,
            "normalized_title": normalized_title,
            "keywords": keywords,
            "popularity_score": float(popularity_score),
            "status": status,
            "created_at": now,
            "updated_at": now,
        }
        rows.append(row)
        _save("search_index.json", rows)
        _append_log(client.get("id"), {"language_code": language_code, "article_id": article_id, "id": new_id}, article_id, 200, False, None)
        return {"tool_name": "upsert_search_index_entry", "data": row, "created": True, "http_status": 200}

    # update existing with lifecycle enforcement
    cur_status = existing.get("status")
    if cur_status != status:
        allowed = lifecycle.get(cur_status, [])
        if status not in allowed:
            _append_log(client.get("id"), {"id": existing.get("id"), "from": cur_status, "to": status}, article_id, 409, False, "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", f"Status transition {cur_status} -> {status} is not allowed.", http_status=409)

    existing["language_code"] = language_code
    existing["article_id"] = article_id
    existing["title"] = title
    existing["normalized_title"] = normalized_title
    existing["keywords"] = keywords
    existing["popularity_score"] = float(popularity_score)
    existing["status"] = status
    existing["updated_at"] = now

    _save("search_index.json", rows)
    _append_log(client.get("id"), {"id": existing.get("id"), "language_code": language_code, "article_id": article_id}, article_id, 200, False, None)
    return {"tool_name": "upsert_search_index_entry", "data": existing, "created": False, "http_status": 200}

