            _append_log(client.get("id"), {"id": existing.get("id"), "from": cur_status, "to": status}, from_article_id, 409, False, "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", f"Status transition {cur_status} -> {status} is not allowed.", http_status=409)

    # prevent uniqueness conflicts when changing keys (language_code/from/to/edge_type)
    for r in rows:
        if not isinstance(r, dict) or r is existing:
            continue
        if r.get("language_code") == language_code and r.get("from_article_id") == from_article_id and r.get("to_article_id") == to_article_id and r.get("edge_type") == edge_type:
            _append_log(client.get("id"), {"language_code": language_code, "from_article_id": from_article_id, "to_article_id": to_article_id, "edge_type": edge_type}, from_article_id, 409, False, "UNIQUE_VIOLATION")
            return _err("CONFLICT", "unique(language_code, from_article_id, to_article_id, edge_type) violated.", http_status=409)

    existing["language_code"] = language_code
    existing["from_article_id"] = from_article_id
    existing["to_article_id"] = to_article_id
    existing["edge_type"] = edge_type
    existing["weight"] = float(weight)
    existing["status"] = status
    existing["updated_at"] = now

    _save("article_graph.json", rows)
    _append_log(client.get("id"), {"id": existing.get("id"), "language_code": language_code, "from_article_id": from_article_id, "to_article_id": to_article_id, "edge_type": edge_type}, from_article_id, 200, False, None)
    return {"tool_name": "upsert_article_graph_edge", "data": existing, "created": False, "http_status": 200}
